    constexpr size_t MAX_REST_MESHES = 1024;
    if (cache.size() >= MAX_REST_MESHES)
    {
        cache.erase(order.front());
        order.pop_front();
    }
    cache.emplace(key, delta);
    order.push_back(key);
    return delta;
}

